/**
 * 角色外貌库服务
 * 负责从世界书读写角色外貌描述（Danbooru 风格 tags）
 * 数据存储在世界书条目 [res]角色外貌库 中，格式为 YAML
 */

import YAML from 'yaml';

/** 世界书中角色外貌库条目的约定名称 */
const CHAR_APPEARANCES_ENTRY_NAME = '[res]角色外貌库';

/**
 * 获取当前角色卡绑定的世界书名称
 * 优先使用角色卡主世界书，其次使用附加世界书中的第一个
 */
async function getTargetWorldbookName(): Promise<string | null> {
  try {
    const charWbs = getCharWorldbookNames('current');
    if (charWbs.primary) return charWbs.primary;
    if (charWbs.additional.length > 0) return charWbs.additional[0];
    // 尝试全局世界书
    const globalWbs = getGlobalWorldbookNames();
    if (globalWbs.length > 0) return globalWbs[0];
  } catch (e) {
    console.warn('[characterAppearances] 获取世界书名称失败:', e);
  }
  return null;
}

/**
 * 从世界书加载角色外貌库
 * @returns Record<角色名, Danbooru tags>
 */
export async function loadCharacterAppearances(): Promise<Record<string, string>> {
  try {
    const wbName = await getTargetWorldbookName();
    if (!wbName) {
      console.info('[characterAppearances] 未找到可用世界书');
      return {};
    }

    const entries = await getWorldbook(wbName);
    const entry = entries.find(e => e.name === CHAR_APPEARANCES_ENTRY_NAME);
    if (!entry) {
      console.info('[characterAppearances] 世界书中未找到角色外貌库条目');
      return {};
    }

    const parsed = YAML.parse(entry.content);
    if (!parsed || typeof parsed !== 'object') return {};

    // 确保所有值都是字符串
    const result: Record<string, string> = {};
    for (const [key, value] of Object.entries(parsed)) {
      if (typeof value === 'string') {
        result[key] = value;
      }
    }
    return result;
  } catch (e) {
    console.warn('[characterAppearances] 加载角色外貌库失败:', e);
    return {};
  }
}

/**
 * 保存角色外貌库到世界书
 * @param appearances Record<角色名, Danbooru tags>
 */
export async function saveCharacterAppearances(appearances: Record<string, string>): Promise<void> {
  try {
    const wbName = await getTargetWorldbookName();
    if (!wbName) {
      throw new Error('未找到可用世界书，无法保存角色外貌库');
    }

    const yamlContent = YAML.stringify(appearances, { lineWidth: 0 });

    const entries = await getWorldbook(wbName);
    const existingEntry = entries.find(e => e.name === CHAR_APPEARANCES_ENTRY_NAME);

    if (existingEntry) {
      // 更新已有条目
      await updateWorldbookWith(wbName, wb => {
        return wb.map(e => {
          if (e.name === CHAR_APPEARANCES_ENTRY_NAME) {
            return { ...e, content: yamlContent };
          }
          return e;
        });
      });
      console.info('[characterAppearances] 角色外貌库已更新');
    } else {
      // 创建新条目（蓝灯常驻，不注入提示词，仅作为数据存储）
      await createWorldbookEntries(wbName, [
        {
          name: CHAR_APPEARANCES_ENTRY_NAME,
          content: yamlContent,
          enabled: false, // 不启用（不注入提示词），仅作为数据存储
          strategy: {
            type: 'constant',
            keys: [],
            keys_secondary: { logic: 'and_any', keys: [] },
            scan_depth: 'same_as_global',
          },
          position: {
            type: 'before_character_definition',
            role: 'system',
            depth: 0,
            order: 999,
          },
          probability: 100,
          recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
          effect: { sticky: null, cooldown: null, delay: null },
        },
      ]);
      console.info('[characterAppearances] 角色外貌库条目已创建');
    }
  } catch (e) {
    console.error('[characterAppearances] 保存角色外貌库失败:', e);
    throw e;
  }
}

/**
 * 添加或更新单个角色的外貌描述
 */
export async function upsertCharacterAppearance(name: string, tags: string): Promise<Record<string, string>> {
  const appearances = await loadCharacterAppearances();
  appearances[name] = tags;
  await saveCharacterAppearances(appearances);
  return appearances;
}

/**
 * 删除单个角色的外貌描述
 */
export async function deleteCharacterAppearance(name: string): Promise<Record<string, string>> {
  const appearances = await loadCharacterAppearances();
  delete appearances[name];
  await saveCharacterAppearances(appearances);
  return appearances;
}
